<?php require_once __DIR__.'/../includes/permissions.php'; ?>
<?php require_role('buyer');$statusList=['pending','confirmed','preparing','ready','shipping','delivered','cancelled'];$filter=in_array($_GET['estado']??'',$statusList,true)?$_GET['estado']:'';$where='buyer_id=?';$params=[user()['buyer_id']];if($filter){$where.=' AND status=?';$params[]=$filter;}$per=10;[$page,$offset]=page_offset($per);$c=db()->prepare("SELECT COUNT(*) FROM orders WHERE $where");$c->execute($params);$total=(int)$c->fetchColumn();$s=db()->prepare("SELECT * FROM orders WHERE $where ORDER BY created_at DESC LIMIT $per OFFSET $offset");$s->execute($params);$orders=$s->fetchAll();$unread=unread_messages_by_order(current_user_id());include __DIR__.'/../includes/header.php';?><div class="dashboard-layout"><?php include __DIR__.'/../includes/sidebar.php';?><section class="dashboard-content"><div class="dashboard-top"><div><span class="eyebrow">Histórico</span><h1>Os meus pedidos</h1></div><form method="get" class="d-flex gap-2 align-items-center"><label class="visually-hidden" for="estado">Estado</label><select id="estado" name="estado" class="form-select" onchange="this.form.submit()"><option value="">Todos os estados</option><?php foreach($statusList as $st):?><option value="<?=e($st)?>" <?=$filter===$st?'selected':''?>><?=e(order_status_label($st))?></option><?php endforeach;?></select><noscript><button class="btn btn-primary">Filtrar</button></noscript></form></div><div class="content-card"><?php if(!$orders):?><p class="text-muted mb-0">Nenhum pedido encontrado<?=$filter?' com este estado':''?>.</p><?php else:?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Pedido</th><th>Data</th><th>Entrega</th><th>Total</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><strong><?=e($o['order_number'])?></strong><?php if(!empty($unread[$o['id']])): ?> <a href="<?=base_path('comprador/pedido-detalhes.php?id='.$o['id'].'#mensagens')?>" class="badge rounded-pill text-bg-danger text-decoration-none" title="Mensagens por ler"><i class="bi bi-chat-dots me-1"></i><?=(int)$unread[$o['id']]?></a><?php endif; ?></td><td><?=date('d/m/Y H:i',strtotime($o['created_at']))?></td><td><?=e($o['district'])?>, <?=e($o['city'])?></td><td><?=money($o['total'])?></td><td><?=order_status_badge($o['status'])?></td><td><a class="btn btn-sm btn-outline-primary" href="<?=base_path('comprador/pedido-detalhes.php?id='.$o['id'])?>">Ver detalhes</a></td></tr><?php endforeach;?></tbody></table></div><?=pagination($page,$per,$total)?><?php endif;?></div></section></div><?php include __DIR__.'/../includes/footer.php';?>
